function renderStats(){const n=document.getElementById("stats-grid");n&&"undefined"!=typeof SUBROTO_INFO&&(n.innerHTML=SUBROTO_INFO.quickStats.map(n=>`\n        <div class="stat-card">\n            <span class="stat-icon">${n.icon}</span>\n            <div class="stat-val">${n.value}</div>\n            <div class="stat-lbl">${n.label}</div>\n        </div>\n    `).join(""))}function renderPipeline(){const n=document.getElementById("pipeline-container");n&&"undefined"!=typeof PLAYER_PIPELINE&&(n.innerHTML=PLAYER_PIPELINE.map((n,e)=>`\n        <div class="pipeline-step">\n            <div class="step-num">${e+1}</div>\n            <div class="step-content">\n                <h3>${n.stage}</h3>\n                <span class="level-tag">${n.level}</span>\n                <p>${n.description}</p>\n            </div>\n        </div>\n    `).join(""))}function renderCategories(){const n=document.getElementById("categories-grid");n&&"undefined"!=typeof AGE_CATEGORIES&&(n.innerHTML=AGE_CATEGORIES.map(n=>`\n        <div class="category-card">\n            <span class="intro-tag">Introduced: ${n.introduced}</span>\n            <h3>⚽ ${n.category}</h3>\n            <p><strong>Official Trophy:</strong> ${n.trophy}</p>\n            <p>${n.description}</p>\n        </div>\n    `).join(""))}function renderAlumni(){const n=document.getElementById("alumni-grid");n&&"undefined"!=typeof FAMOUS_ALUMNI&&(n.innerHTML=FAMOUS_ALUMNI.map(n=>`\n        <div class="alumni-card">\n            <span class="pos-tag">${n.position}</span>\n            <h3>⭐ ${n.name}</h3>\n            <p><strong>School Alma Mater:</strong> ${n.school}</p>\n            <p>${n.achievements}</p>\n        </div>\n    `).join(""))}function renderReferences(){const n=document.getElementById("references-list");n&&"undefined"!=typeof REFERENCES&&(n.innerHTML=REFERENCES.map(n=>`\n        <li>\n            <a href="${n.link}" target="_blank" rel="noopener noreferrer">📚 ${n.text}</a>\n        </li>\n    `).join(""))}function initThemeToggle(){const n=document.getElementById("theme-toggle");n&&n.addEventListener("click",()=>{const e=document.body.classList.toggle("light-theme");localStorage.setItem("theme",e?"light":"dark"),n.textContent=e?"🌙":"☀️"})}document.addEventListener("DOMContentLoaded",()=>{renderStats(),renderPipeline(),renderCategories(),renderAlumni(),renderReferences(),initThemeToggle()});